#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#include <float.h>
#include <stdint.h>
__global__ void min_dim1_kernel(const float* __restrict__ x,
                                float* __restrict__ out,
                                int B, int M, int N,
                                long long total) {
    // Block-cooperative split-M reduction: each block owns one batch slice
    // and a tile of 32 columns. The 8 warps of the block split the long M
    // range, so every warp load remains a fully coalesced 128-byte
    // transaction while the per-thread dependency chain is 8x shorter and
    // 8x more independent row streams are in flight. Partial minima are
    // combined through shared memory by the first warp.
    __shared__ float smin[8][32];
    const int b = blockIdx.x;
    const int j = blockIdx.y * 32 + threadIdx.x;
    const long long stride = (long long)N;
    float mn = FLT_MAX;
    if (j < N) {
        const float* p = x + ((size_t)b * (size_t)M) * (size_t)stride + (size_t)j;
        int i = threadIdx.y;
        for (; i + 24 < M; i += 32) {
            const float v0 = __ldg(p + (size_t)i * (size_t)stride);
            const float v1 = __ldg(p + (size_t)(i + 8) * (size_t)stride);
            const float v2 = __ldg(p + (size_t)(i + 16) * (size_t)stride);
            const float v3 = __ldg(p + (size_t)(i + 24) * (size_t)stride);
            mn = fminf(mn, fminf(fminf(v0, v1), fminf(v2, v3)));
        }
        for (; i < M; i += 8) {
            mn = fminf(mn, __ldg(p + (size_t)i * (size_t)stride));
        }
    }
    smin[threadIdx.y][threadIdx.x] = mn;
    __syncthreads();
    if (threadIdx.y == 0 && j < N) {
        #pragma unroll
        for (int k = 1; k < 8; ++k) {
            mn = fminf(mn, smin[k][threadIdx.x]);
        }
        out[((size_t)b * (size_t)stride) + (size_t)j] = mn;
    }
